@TestOn('browser')
library;

// Parsing must work when compiled to JavaScript (the web app), where 64-bit
// integers and typed-data views behave differently from the VM.
import 'dart:convert';
import 'dart:typed_data';

import 'package:idftool/idftool.dart';
import 'package:test/test.dart';

// test/fixtures/nvs/types.bin — every primitive type, strings and a blob.
const _typesImage = '';

void main() {
  test('parses a python-generated image under dart2js', () {
    final image = parseNvs(base64Decode(_typesImage));
    expect(image.errors, isEmpty);
    expect(image.entries, isNotEmpty);
    expect(nvsToCsv(image.entries), contains('i16_v,data,i16,-2'));
    expect(formatNvsEntries(image.entries), contains('i16_v'));
  });

  test('generate and edit round-trip under dart2js', () {
    final blobHex = [for (var i = 0; i < 300; i++) ((i * 7 + 3) & 0xFF).toRadixString(16).padLeft(2, '0')].join();
    final image = generateNvsImage(
        'key,type,encoding,value\n'
        'ns,namespace,,\n'
        'k,data,u64,18446744073709551615\n'
        'neg,data,i64,-9223372036854775808\n'
        'mid,data,i64,-1234567890123\n'
        'u32,data,u32,4294967295\n'
        's,data,string,hi\n'
        'b,data,hex2bin,$blobHex\n',
        0x4000);
    final parsed = parseNvs(image, strict: true);
    expect(parsed.get('ns', 'k')!.valueText, '18446744073709551615');
    expect(parsed.get('ns', 'k')!.value, (BigInt.one << 64) - BigInt.one);
    expect(parsed.get('ns', 'neg')!.value, -(BigInt.one << 63));
    expect(parsed.get('ns', 'neg')!.valueText, '-9223372036854775808');
    expect(parsed.get('ns', 'mid')!.value, BigInt.from(-1234567890123));
    expect(parsed.get('ns', 'u32')!.value, 0xFFFFFFFF);
    expect(hexEncode(parsed.get('ns', 'b')!.value as List<int>), blobHex);
    expect(nvsToCsv(parsed.entries), contains('k,data,u64,18446744073709551615\n'));
    expect(nvsToCsv(parsed.entries), contains('neg,data,i64,-9223372036854775808\n'));

    final edited = applyNvsEdits(image, [
      const NvsEdit.set('ns', 's', type: NvsType.string, value: 'there'),
      NvsEdit.set('ns', 'k', type: NvsType.u64, value: BigInt.one << 63),
      parseNvsSetSpec('ns:neg=-1'),
      parseNvsSetSpec('ns:mid:i64=-1234567890123'), // identical → unchanged
      NvsEdit.set('ns', 'b', type: NvsType.blob, value: Uint8List.fromList([1, 2, 3])),
    ].map((e) => e.type == null ? resolveUntypedNvsEdits(parsed, [e]).single : e).toList());
    expect(edited.changes.map((c) => c.action), [
      NvsChangeAction.set,
      NvsChangeAction.set,
      NvsChangeAction.set,
      NvsChangeAction.unchanged,
      NvsChangeAction.set,
    ]);
    final after = parseNvs(edited.image, strict: true);
    expect(after.get('ns', 's')!.value, 'there');
    expect(after.get('ns', 'k')!.value, BigInt.one << 63);
    expect(after.get('ns', 'k')!.valueText, '9223372036854775808');
    expect(after.get('ns', 'neg')!.value, -BigInt.one);
    expect(after.get('ns', 'b')!.value, [1, 2, 3]);
    expect(describeNvsChange(edited.changes[1]), '  ~ ns:k (u64): 18446744073709551615 -> 9223372036854775808');
    expect(looksLikeNvsBinary(edited.image), isTrue);
  });
}
